node -e "
const fs = require('fs');
const path = require('path');

const chunks = [];

process.stdin.on('data', d => chunks.push(d));

process.stdin.on('end', () => {
  try {
    const input = JSON.parse(Buffer.concat(chunks).toString());
    const prompt = String(input.userPrompt || '').toLowerCase();

    const configPath = path.join(process.cwd(), '.kiro', 'agentpicker.json');
    const configFile = fs.readFileSync(configPath, 'utf8');
    const config = JSON.parse(configFile);

    const agents = config.agents || {};
    const priority = (config.routing && config.routing.priority) || [];

    const candidates = [];

    for (const [key, agent] of Object.entries(agents)) {
      const keywords = Array.isArray(agent.keywords)
        ? agent.keywords
        : [];

      const matches = keywords.filter(keyword => {
        const normalizedKeyword = String(keyword).toLowerCase().trim();
        return normalizedKeyword.length > 0 && prompt.includes(normalizedKeyword);
      });

      if (matches.length > 0) {
        const priorityIndex = priority.indexOf(agent.category);
        const effectivePriority = priorityIndex === -1
          ? Number.MAX_SAFE_INTEGER
          : priorityIndex + 1;

        candidates.push({
          key,
          category: agent.category,
          agent: agent.name,
          model: agent.model,
          priority: effectivePriority,
          matches
        });
      }
    }

    if (candidates.length === 0) {
      process.stdout.write(
        '\n' +
        '╔══════════════════════════════════════════════════════════════╗\n' +
        '║                 SDLC PHASE OBSERVER                         ║\n' +
        '╠══════════════════════════════════════════════════════════════╣\n' +
        '║ Observer Match    : NONE                                     ║\n' +
        '║ Candidate Agent   : NONE                                     ║\n' +
        '║ Candidate Model   : NONE                                     ║\n' +
        '║ Observer Only     : YES                                      ║\n' +
        '║ Actual Router     : @TravelPlatform                          ║\n' +
        '╚══════════════════════════════════════════════════════════════╝\n' +
        '\n'
      );
      return process.exit(0);
    }

    candidates.sort((a, b) => {
      if (a.priority !== b.priority) {
        return a.priority - b.priority;
      }

      return b.matches.length - a.matches.length;
    });

    const selected = candidates[0];

    const confidence =
      candidates.length === 1 && selected.matches.length >= 2
        ? 'HIGH'
        : candidates.length === 1
          ? 'MEDIUM'
          : 'MEDIUM';

    process.stdout.write(
      '\n' +
      '╔══════════════════════════════════════════════════════════════╗\n' +
      '║                 SDLC PHASE OBSERVER                         ║\n' +
      '╠══════════════════════════════════════════════════════════════╣\n' +
      '║ Observer Match    : ' + selected.category.padEnd(40) + '║\n' +
      '║ Candidate Agent   : ' + selected.agent.padEnd(40) + '║\n' +
      '║ Candidate Model   : ' + selected.model.padEnd(40) + '║\n' +
      '║ Priority          : ' + String(selected.priority).padEnd(40) + '║\n' +
      '║ Keyword Matches   : ' + selected.matches.join(', ').slice(0, 38).padEnd(40) + '║\n' +
      '║ Confidence        : ' + confidence.padEnd(40) + '║\n' +
      '║ Observer Only     : YES                                      ║\n' +
      '║ Actual Router     : @TravelPlatform                          ║\n' +
      '╚══════════════════════════════════════════════════════════════╝\n' +
      '\n' +
      '[Phase Observer] This is an observation only. @TravelPlatform is responsible for actual delegation.\n' +
      '\n'
    );

    process.exit(0);
  } catch (error) {
    // Hooks must never block the user's request.
    process.exit(0);
  }
});
"
